// Synthetic reviewed checker. Not generated by a Harness.
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
const base_url = process.env.BASE_URL;
const checks = [];
const call = (path, method = 'GET', body) => fetch(base_url + path, { method, headers: { 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined, signal: AbortSignal.timeout(10000) });
const pass = name => checks.push({ name, status: 'pass' });
assert.deepEqual(await (await call('/health')).json(), { status: 'ok', service: 'tailnet-todo', node: 'mac' }); pass('health');
assert.ok(Array.isArray((await (await call('/todos')).json()).todos)); pass('list');
const title = `fixture-${randomUUID()}`;
const r = await call('/todos', 'POST', { title }); assert.equal(r.status, 201); const item = await r.json(); assert.equal(item.title, title); pass('create');
assert.ok((await (await call('/todos')).json()).todos.some(t => t.id === item.id)); pass('list_verify_created');
const update = await call(`/todos/${item.id}`, 'PATCH', { completed: true }); assert.equal(update.status, 200); assert.equal((await update.json()).completed, true); pass('patch');
assert.ok((await (await call('/todos')).json()).todos.some(t => t.id === item.id && t.completed)); pass('list_verify_patched');
assert.equal((await call(`/todos/${item.id}`, 'DELETE')).status, 204); pass('delete');
assert.ok(!(await (await call('/todos')).json()).todos.some(t => t.id === item.id)); pass('list_verify_removed');
console.log(JSON.stringify({ ok: true, base_url, checks }));
